const validationErrors = [];
const persistenceIsObject = $json.persistence !== null
  && typeof $json.persistence === 'object'
  && !Array.isArray($json.persistence);
const persistence = persistenceIsObject ? $json.persistence : {};

if ($json.schema_version !== '1.0') {
  validationErrors.push('Invalid schema_version: expected 1.0.');
}
if ($json.workflow_version !== '1.0') {
  validationErrors.push('Invalid workflow_version: expected 1.0.');
}
if ($json.route !== 'chapter.persistence.created') {
  validationErrors.push('Invalid route: expected chapter.persistence.created.');
}
if ($json.status !== 'ready') {
  validationErrors.push('Invalid status: expected ready.');
}
if (!persistenceIsObject) {
  validationErrors.push('Invalid persistence: expected an object.');
}
if (typeof persistence.chapter_uuid !== 'string' || !persistence.chapter_uuid.trim()) {
  validationErrors.push('persistence.chapter_uuid is required.');
}
if (typeof persistence.workspace_uuid !== 'string' || !persistence.workspace_uuid.trim()) {
  validationErrors.push('persistence.workspace_uuid is required.');
}
if (typeof persistence.novel_uuid !== 'string' || !persistence.novel_uuid.trim()) {
  validationErrors.push('persistence.novel_uuid is required.');
}
if (typeof persistence.storage_provider !== 'string' || !persistence.storage_provider.trim()) {
  validationErrors.push('persistence.storage_provider is required.');
}
if (typeof persistence.storage_strategy !== 'string' || !persistence.storage_strategy.trim()) {
  validationErrors.push('persistence.storage_strategy is required.');
}
if (!Array.isArray(persistence.pending_operations)) {
  validationErrors.push('persistence.pending_operations must be an array.');
}

return [{
  json: {
    ...$json,
    status: validationErrors.length === 0 ? 'ready' : 'error',
    is_valid: validationErrors.length === 0,
    validation_errors: validationErrors,
  },
}];

const persistence = $json.persistence !== null
  && typeof $json.persistence === 'object'
  && !Array.isArray($json.persistence)
  ? $json.persistence
  : {};

return [{
  json: {
    is_valid: $json.is_valid === true,
    validation_errors: Array.isArray($json.validation_errors) ? $json.validation_errors : [],
    chapter_uuid: persistence.chapter_uuid ?? '',
    workspace_uuid: persistence.workspace_uuid ?? '',
    novel_uuid: persistence.novel_uuid ?? '',
    storage_provider: persistence.storage_provider ?? '',
    storage_strategy: persistence.storage_strategy ?? '',
    storage_status: persistence.storage_status ?? '',
    pending_operations: persistence.pending_operations ?? [],
  },
}];

const normalizeToken = (value) => typeof value === 'string'
  ? value.trim().toLowerCase().replace(/\s+/gu, '_')
  : '';
const normalizedOperations = Array.isArray($json.pending_operations)
  ? $json.pending_operations.map((operation) => {
      if (typeof operation === 'string') return operation.trim();
      if (operation && typeof operation === 'object' && !Array.isArray(operation)) return { ...operation };
      return operation;
    })
  : [];

return [{
  json: {
    ...$json,
    chapter_uuid: typeof $json.chapter_uuid === 'string' ? $json.chapter_uuid.trim() : '',
    workspace_uuid: typeof $json.workspace_uuid === 'string' ? $json.workspace_uuid.trim() : '',
    novel_uuid: typeof $json.novel_uuid === 'string' ? $json.novel_uuid.trim() : '',
    storage_provider: normalizeToken($json.storage_provider),
    storage_strategy: normalizeToken($json.storage_strategy),
    storage_status: normalizeToken($json.storage_status) || 'pending',
    pending_operations: normalizedOperations,
  },
}];

if ($json.is_valid !== true) {
  return [{
    json: {
      is_valid: false,
      validation_errors: $json.validation_errors ?? [],
      storage: null,
    },
  }];
}

return [{
  json: {
    is_valid: true,
    validation_errors: [],
    storage: {
      chapter_uuid: $json.chapter_uuid,
      workspace_uuid: $json.workspace_uuid,
      novel_uuid: $json.novel_uuid,
      storage_provider: $json.storage_provider,
      storage_strategy: $json.storage_strategy,
      storage_status: $json.storage_status,
      pending_operations: $json.pending_operations,
    },
  },
}];

const isValid = $json.is_valid === true;

return [{
  json: {
    schema_version: '1.0',
    workflow_version: '1.0',
    route: 'storage.intake.created',
    target: 'WF-005-P02',
    status: isValid ? 'ready' : 'error',
    is_valid: isValid,
    validation_errors: $json.validation_errors ?? [],
    storage: isValid ? $json.storage : null,
  },
}];
